class CounterNotFound(Exception):
    """
    Raised when counter with provided id couldn't be find in BTS Counters
    """
    pass


class NoCountersReported(Exception):
    """
    Raised when there were no counters found
    during verification for a given time period
    """
    pass


class DifferenceBetweenCountersExceedsDesiredRange(Exception):
    """
    Raised when difference between counters is either smaller or bigger than the desired range
    """
    pass
